/**
 * Cube state as a 54-character Kociemba facelet string: 9 stickers per face in
 * URFDLB order, each face read row by row as seen from outside the cube. Each
 * character names the face whose color the sticker shows. This is the same
 * string the GAN cube's FACELETS event decodes to, so the two compare directly.
 *
 * Geometry uses the Three.js frame: +x = R, +y = U, +z = F (right-handed). Move
 * permutations are generated by rotating sticker positions in that frame.
 */

import { FACES, type Face, type Move } from './moves';

export type Vec3 = [number, number, number];

export const SOLVED = FACES.map((face) => face.repeat(9)).join('');

export const FACE_NORMAL: Record<Face, Vec3> = {
  U: [0, 1, 0],
  R: [1, 0, 0],
  F: [0, 0, 1],
  D: [0, -1, 0],
  L: [-1, 0, 0],
  B: [0, 0, -1],
};

// Reading order of each face: direction of increasing column, then of increasing row.
const READING_AXES: Record<Face, [Vec3, Vec3]> = {
  U: [[1, 0, 0], [0, 0, 1]], // seen from above, B edge on top
  R: [[0, 0, -1], [0, -1, 0]],
  F: [[1, 0, 0], [0, -1, 0]],
  D: [[1, 0, 0], [0, 0, -1]], // seen from below, F edge on top
  L: [[0, 0, 1], [0, -1, 0]],
  B: [[-1, 0, 0], [0, -1, 0]],
};

export interface Sticker {
  /** Grid position of the cubie carrying the sticker, components in {-1, 0, 1}. */
  pos: Vec3;
  /** Outward normal of the sticker. */
  normal: Vec3;
}

export const STICKERS: Sticker[] = FACES.flatMap((face) => {
  const normal = FACE_NORMAL[face];
  const [col, row] = READING_AXES[face];
  const stickers: Sticker[] = [];
  for (let r = -1; r <= 1; r++) {
    for (let c = -1; c <= 1; c++) {
      const pos = normal.map((n, i) => n + c * col[i] + r * row[i]) as Vec3;
      stickers.push({ pos, normal });
    }
  }
  return stickers;
});

const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

/** Rotate `v` a quarter turn clockwise as seen looking at `face` from outside. */
function rotateClockwise(v: Vec3, face: Face): Vec3 {
  // Rodrigues with angle -90 degrees: v' = n (n.v) - n x v
  const n = FACE_NORMAL[face];
  const cross: Vec3 = [
    n[1] * v[2] - n[2] * v[1],
    n[2] * v[0] - n[0] * v[2],
    n[0] * v[1] - n[1] * v[0],
  ];
  const d = dot(n, v);
  return [n[0] * d - cross[0], n[1] * d - cross[1], n[2] * d - cross[2]];
}

const stickerKey = (pos: Vec3, normal: Vec3) => `${pos.join()}|${normal.join()}`;
const STICKER_INDEX = new Map(STICKERS.map((s, i) => [stickerKey(s.pos, s.normal), i]));

/** Facelet index of the sticker at a cubie position facing a direction. */
export function stickerIndex(pos: Vec3, normal: Vec3): number {
  return STICKER_INDEX.get(stickerKey(pos, normal))!;
}

/** TURNS[face][amount][i] = slot whose sticker lands in slot i after the turn. */
const TURNS = Object.fromEntries(
  FACES.map((face) => {
    const quarter = STICKERS.map((_, i) => i);
    STICKERS.forEach((s, from) => {
      if (dot(s.pos, FACE_NORMAL[face]) !== 1) return; // not in the turning layer
      const to = STICKER_INDEX.get(
        stickerKey(rotateClockwise(s.pos, face), rotateClockwise(s.normal, face)),
      )!;
      quarter[to] = from;
    });
    const half = quarter.map((i) => quarter[i]);
    const three = half.map((i) => quarter[i]);
    return [face, [null, quarter, half, three]];
  }),
) as Record<Face, [null, number[], number[], number[]]>;

export function applyMove(state: string, move: Move): string {
  const perm = TURNS[move.face][move.amount];
  let out = '';
  for (let i = 0; i < 54; i++) out += state[perm[i]];
  return out;
}

export function applyMoves(state: string, moves: Move[]): string {
  return moves.reduce(applyMove, state);
}

export function isSolved(state: string): boolean {
  return state === SOLVED;
}
